import numpy as np
import time


def C_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def smooth(h, k):
    """Simple local averaging smoothing of step heights."""
    if k <= 1:
        return h
    kernel = np.ones(k) / k
    return np.convolve(h, kernel, mode='same')


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.0  # margin

    # Start from best known / start
    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        if best.size == 0 or best.sum() <= 0:
            best = np.ones(50)
    else:
        best = np.ones(50)

    # Normalise
    best = best / best.max()
    bestC = C_of(best)

    # Candidate N values to try (step count matters: C = 2N max(conv)/(sum)^2)
    # Larger N gives finer resolution; try a range.
    Ns = [50, 100, 200, 400, 800, 1600, 3200, 6400, 12800]

    # Initial shapes to seed: triangular-ish (optimal for continuous problem is triangle-ish)
    def tri(N):
        x = np.linspace(-1, 1, N)
        return np.maximum(0.0, 1.0 - np.abs(x))

    def bump(N):
        x = np.linspace(-1, 1, N)
        return np.maximum(0.0, 1.0 - x * x)

    def flat(N):
        return np.ones(N)

    seeds = [tri, bump, flat]

    # Phase 1: evaluate seeds at various N
    for N in Ns:
        if time.process_time() - t0 > deadline * 0.3:
            break
        for fn in seeds:
            h = fn(N)
            if h.sum() <= 0:
                continue
            c = C_of(h)
            if c < bestC:
                bestC = c
                best = h.copy()

    # Phase 2: local refinement via coordinate perturbations / smoothing
    # Use a hill-climbing scheme on heights.
    rng = np.random.default_rng(12345)

    def refine(h, c, iters, tlimit):
        h = h.copy()
        N = len(h)
        step = 0.05
        for it in range(iters):
            if time.process_time() - t0 > tlimit:
                break
            # try smoothing
            for k in [3, 5, 9, 15]:
                if k >= N:
                    continue
                h2 = smooth(h, k)
                c2 = C_of(h2)
                if c2 < c:
                    h, c = h2, c2
                    break
            # try random multiplicative perturbations on a block
            if it % 5 == 0:
                h2 = h.copy()
                idx = rng.integers(0, N, size=max(1, N // 20))
                h2[idx] *= (1.0 + step * rng.standard_normal(len(idx)))
                h2 = np.maximum(h2, 0.0)
                if h2.sum() > 0:
                    c2 = C_of(h2)
                    if c2 < c:
                        h, c = h2, c2
            # try add edge taper
            if it % 7 == 0:
                h2 = h.copy()
                m = max(1, N // 10)
                taper = np.linspace(0, 1, m)
                h2[:m] *= taper
                h2[-m:] *= taper[::-1]
                if h2.sum() > 0:
                    c2 = C_of(h2)
                    if c2 < c:
                        h, c = h2, c2
            # occasional step shrink
            if it % 50 == 49:
                step *= 0.7
        return h, c

    # Refine best at its N, and also try refining seeds at larger N
    best, bestC = refine(best, bestC, 300, deadline)

    # Try fresh triangular seeds at large N with refinement
    for N in [800, 1600, 3200, 6400, 12800]:
        if time.process_time() - t0 > deadline * 0.7:
            break
        for fn in seeds:
            h = fn(N)
            c = C_of(h)
            if c < bestC:
                best, bestC = h, c
        # refine this best
        best, bestC = refine(best, bestC, 200, deadline)

    # Final safety: ensure valid
    best = np.asarray(best, dtype=float)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    if len(best) > 30000:
        best = best[:30000]

    return best

import numpy as np
import time


def construct(budget_seconds, start):
    """Minimise C(f) = 2N max(h*h)/sum(h)^2 via local multiplicative search on N and heights."""
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 50
    if start is not None:
        h = np.asarray(start, dtype=float).ravel()
        if h.size > 0 and h.size <= 30000:
            N = h.size
            h = np.clip(h, 0.0, None)
            if h.sum() <= 0:
                h = np.ones(N)
        else:
            h = np.ones(N)
    else:
        h = np.ones(N)

    def score(h):
        s = h.sum()
        if s <= 0:
            return np.inf
        return 2.0 * h.size * np.max(np.convolve(h, h)) / (s * s)

    best = score(h)
    rng = np.random.default_rng(12345)

    # Multiplicative perturbation search (scale-invariant, keeps positivity).
    # Try a few N values around the current one; also grow N since finer grids can help.
    N_candidates = sorted(set(
        [N] + [max(1, N + d) for d in (-1, 1, -2, 2, -5, 5)] +
        [int(N * f) for f in (0.8, 1.2, 1.5, 2.0, 3.0)]
    ))
    N_candidates = [n for n in N_candidates if 1 <= n <= 30000]

    def try_improve(h, best, steps, rng):
        n = h.size
        for _ in range(steps):
            if time.process_time() > deadline:
                return h, best, True
            i = rng.integers(0, n)
            old = h[i]
            # multiplicative move
            fac = np.exp(rng.normal(0.0, 0.5))
            h[i] = old * fac
            s = score(h)
            if s < best:
                best = s
            else:
                h[i] = old
        return h, best, False

    # Coarse exploration over N with cheap random search.
    for nc in N_candidates:
        if time.process_time() > deadline:
            break
        if nc == N:
            cand = h.copy()
        else:
            # resample current shape to new size
            x_old = np.linspace(0, 1, h.size)
            x_new = np.linspace(0, 1, nc)
            cand = np.interp(x_new, x_old, h)
            if cand.sum() <= 0:
                cand = np.ones(nc)
        cand, cand_score, timeout = try_improve(cand, score(cand), 300, rng)
        if cand_score < best:
            h, best = cand, cand_score
        if timeout:
            break

    # Fine local search on the best N.
    while time.process_time() < deadline:
        h, best, timeout = try_improve(h, best, 200, rng)
        if timeout:
            break

    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        h = np.ones(max(1, h.size))
    return h

import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _convolve_max(h):
    return float(np.max(np.convolve(h, h)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.80

    def elapsed():
        return time.process_time() - t0

    def trim(h):
        nz = np.nonzero(h > 1e-12 * h.max())[0]
        if len(nz) == 0:
            return h
        return h[nz[0]:nz[-1] + 1]

    # Seed
    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        m = h.max()
        if m > 0:
            h /= m
    else:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h = np.exp(-(x / 0.18) ** 2)

    h = trim(h)
    best = h.copy()
    bestC = _C(best)

    rng = np.random.default_rng(987654321)

    # Work in log space for multiplicative coordinate updates.
    def evaluate(v):
        return _C(np.exp(v))

    # Try upsampling: many tiny steps can approach the smooth optimal shape.
    # We also try several N values.
    def upsample(h, N2):
        xold = np.linspace(0, 1, len(h))
        xnew = np.linspace(0, 1, N2)
        return np.maximum(np.interp(xnew, xold, h), 0)

    # Local search in log-space, with adaptive step and per-coordinate moves.
    def local_search(h0, deadline_frac=1.0):
        nonlocal best, bestC
        h = h0.copy()
        v = np.log(np.maximum(h, 1e-12))
        curC = _C(h)
        step = 0.3
        stall = 0
        while elapsed() < budget * deadline_frac:
            improved = False
            N = len(v)
            order = rng.permutation(N)
            for idx in order:
                if elapsed() >= budget * deadline_frac:
                    break
                old = v[idx]
                bestlocal = old
                bestlocalC = curC
                for d in (step, -step, 0.5 * step, -0.5 * step):
                    v[idx] = old + d
                    c = evaluate(v)
                    if c < bestlocalC - 1e-15:
                        bestlocalC = c
                        bestlocal = v[idx]
                v[idx] = bestlocal
                if bestlocalC < curC - 1e-15:
                    curC = bestlocalC
                    improved = True
            if curC < bestC:
                bestC = curC
                best = np.exp(v).copy()
            if not improved:
                stall += 1
                step *= 0.6
                if step < 1e-5:
                    break
            else:
                stall = 0
                step = min(step * 1.1, 0.5)
        return np.exp(v), curC

    # First: try upsampling the seed and doing local search on larger N.
    # Larger N gives finer resolution and generally lower C.
    candidates_N = []
    baseN = len(best)
    for mult in (2, 4, 8, 16, 32):
        n = baseN * mult
        if n <= 30000:
            candidates_N.append(n)
    # Add some fixed sizes
    for n in (100, 200, 400, 800, 1600, 3000):
        if n <= 30000 and n not in candidates_N:
            candidates_N.append(n)

    # Allocate budget across candidates, focusing on larger N.
    # Try each briefly, keep the best, then refine.
    best_overall = best.copy()
    bestC_overall = bestC

    for n in candidates_N:
        if elapsed() >= budget * 0.5:
            break
        h_up = upsample(best, n)
        # quick local search on this size with a small time slice
        slice_end = min(budget * 0.5, elapsed() + budget * 0.08)
        v = np.log(np.maximum(h_up, 1e-12))
        curC = _C(h_up)
        step = 0.3
        while elapsed() < slice_end:
            improved = False
            order = rng.permutation(len(v))
            for idx in order:
                if elapsed() >= slice_end:
                    break
                old = v[idx]
                bl = old
                blc = curC
                for d in (step, -step):
                    v[idx] = old + d
                    c = evaluate(v)
                    if c < blc - 1e-15:
                        blc = c
                        bl = v[idx]
                v[idx] = bl
                if blc < curC - 1e-15:
                    curC = blc
                    improved = True
            if not improved:
                step *= 0.6
                if step < 1e-5:
                    break
        if curC < bestC_overall:
            bestC_overall = curC
            best_overall = np.exp(v).copy()

    # Now refine the best_overall with remaining budget.
    best = best_overall
    bestC = bestC_overall

    # Possibly try a couple of different N near the best size for a final refinement.
    refine_sizes = []
    bn = len(best)
    for dn in (-2, -1, 0, 1, 2):
        n = bn + dn
        if 2 <= n <= 30000:
            refine_sizes.append(n)
    # Also try doubling once more if room
    if bn * 2 <= 30000:
        refine_sizes.append(bn * 2)

    for n in refine_sizes:
        if elapsed() >= budget * 0.9:
            break
        h_cand = upsample(best, n) if n != bn else best.copy()
        slice_end = min(budget * 0.95, elapsed() + budget * 0.15)
        v = np.log(np.maximum(h_cand, 1e-12))
        curC = _C(h_cand)
        step = 0.2
        while elapsed() < slice_end:
            improved = False
            order = rng.permutation(len(v))
            for idx in order:
                if elapsed() >= slice_end:
                    break
                old = v[idx]
                bl = old
                blc = curC
                for d in (step, -step, 0.5 * step, -0.5 * step):
                    v[idx] = old + d
                    c = evaluate(v)
                    if c < blc - 1e-15:
                        blc = c
                        bl = v[idx]
                v[idx] = bl
                if blc < curC - 1e-15:
                    curC = blc
                    improved = True
            if not improved:
                step *= 0.6
                if step < 1e-6:
                    break
        if curC < bestC:
            bestC = curC
            best = np.exp(v).copy()

    # Final trim
    best = trim(best)
    if best.sum() <= 0:
        best = np.ones(50)
    if len(best) > 30000:
        best = upsample(best, 30000)
    return best

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _trim(h):
    nz = np.nonzero(h > 1e-12 * h.max())[0]
    if len(nz) == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _resample(h, N):
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    return np.maximum(np.interp(xnew, xold, h), 0)


def _C_and_deriv(h):
    """Return C and the gradient of the (convolved peak) w.r.t. h."""
    n = len(h)
    s = h.sum()
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    peak = conv[k]
    C = 2.0 * n * peak / (s * s)
    # d(peak)/dh[i] = 2*h[k-i] for valid i
    g = np.zeros(n)
    lo = max(0, k - n + 1)
    hi = min(n - 1, k)
    for i in range(lo, hi + 1):
        g[i] = 2.0 * h[k - i]
    # C = 2n*peak/s^2 ; dC/dh = 2n/s^2 * g - 4n*peak/s^3 * 1
    dC = (2.0 * n / (s * s)) * g - (4.0 * n * peak / (s * s * s))
    return C, dC


def _gradient_descent(h, budget_end, t0, rng, max_iter=2000):
    """Projected gradient descent with line search on the exact C."""
    h = h.copy()
    h /= h.max()
    C = _C(h)
    lr = 1e-3
    for _ in range(max_iter):
        if time.process_time() - t0 >= budget_end:
            break
        C, dC = _C_and_deriv(h)
        # normalize gradient scale
        gn = np.linalg.norm(dC)
        if gn < 1e-15:
            break
        # line search
        best_h, best_C = h, C
        for _ls in range(8):
            trial = h - lr * dC
            trial = np.maximum(trial, 0)
            if trial.sum() <= 0:
                lr *= 0.5
                continue
            tc = _C(trial)
            if tc < best_C:
                best_h, best_C = trial, tc
                break
            lr *= 0.5
        if best_C < C - 1e-15:
            h = best_h
            C = best_C
            lr *= 1.3
        else:
            lr *= 0.5
            if lr < 1e-12:
                break
    return h, C


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.80

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.max() > 0:
            h /= h.max()
    else:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h = np.exp(-(x / 0.18) ** 2)

    h = _trim(h)
    best = h.copy()
    bestC = _C(best)
    rng = np.random.default_rng(12345)

    # 1) projected gradient descent at current resolution
    hg, Cg = _gradient_descent(best, budget * 0.35, t0, rng, max_iter=5000)
    if Cg < bestC:
        bestC, best = Cg, hg.copy()

    # 2) coordinate-wise multiplicative polish (cheap, precise)
    cur = best.copy()
    curC = bestC
    logstep = 0.05
    while time.process_time() - t0 < budget * 0.65:
        improved = False
        order = rng.permutation(len(cur))
        for idx in order:
            if time.process_time() - t0 >= budget * 0.65:
                break
            old = cur[idx]
            if old <= 0:
                continue
            bl, blc = old, curC
            for fac in (np.exp(logstep), np.exp(-logstep)):
                cur[idx] = old * fac
                c = _C(cur)
                if c < blc - 1e-16:
                    blc, bl = c, old * fac
            cur[idx] = bl
            if blc < curC - 1e-16:
                curC = blc
                improved = True
        if curC < bestC:
            bestC, best = curC, cur.copy()
        if not improved:
            logstep *= 0.5
            if logstep < 1e-4:
                break

    # 3) resample to higher N and repeat gradient + polish
    while time.process_time() - t0 < budget * 0.85:
        N0 = len(best)
        if N0 >= 30000:
            break
        N1 = min(30000, int(N0 * 1.6) + 1)
        cand = _resample(best, N1)
        candC = _C(cand)
        if candC < bestC + 1e-3:
            bestC, best = candC, cand
            hg, Cg = _gradient_descent(best, budget * 0.82, t0, rng, max_iter=3000)
            if Cg < bestC:
                bestC, best = Cg, hg.copy()
            cur = best.copy()
            curC = bestC
            logstep = 0.03
            while time.process_time() - t0 < budget * 0.85:
                improved = False
                order = rng.permutation(len(cur))
                for idx in order:
                    if time.process_time() - t0 >= budget * 0.85:
                        break
                    old = cur[idx]
                    if old <= 0:
                        continue
                    bl, blc = old, curC
                    for fac in (np.exp(logstep), np.exp(-logstep)):
                        cur[idx] = old * fac
                        c = _C(cur)
                        if c < blc - 1e-16:
                            blc, bl = c, old * fac
                    cur[idx] = bl
                    if blc < curC - 1e-16:
                        curC = blc
                        improved = True
                if curC < bestC:
                    bestC, best = curC, cur.copy()
                if not improved:
                    logstep *= 0.5
                    if logstep < 1e-4:
                        break
        else:
            break

    # 4) final polish with tiny steps
    cur = best.copy()
    curC = bestC
    ls = 0.01
    while time.process_time() - t0 < budget:
        improved = False
        order = rng.permutation(len(cur))
        for idx in order:
            if time.process_time() - t0 >= budget:
                break
            old = cur[idx]
            if old <= 0:
                continue
            bl, blc = old, curC
            for fac in (1 + ls, 1 - ls):
                cur[idx] = old * fac
                c = _C(cur)
                if c < blc - 1e-17:
                    blc, bl = c, old * fac
            cur[idx] = bl
            if blc < curC - 1e-17:
                curC = blc
                improved = True
        if curC < bestC:
            bestC, best = curC, cur.copy()
        if not improved:
            ls *= 0.5
            if ls < 1e-5:
                break

    best = _trim(best)
    if best.sum() <= 0:
        best = np.ones(50)
    if len(best) > 30000:
        best = _resample(best, 30000)
    print(f"final C={_C(best):.9f} N={len(best)} CPU={time.process_time()-t0:.2f}s")
    return best

