def _refine(h, rng, t0, deadline, rounds=3):
    """Multiplicative coordinate descent with geometric step sizes."""
    cur = h.copy()
    curC = _C(cur)
    for r in range(rounds):
        step = 0.2 * (0.4 ** r)
        improved = True
        while improved and time.process_time() - t0 < deadline:
            improved = False
            order = rng.permutation(len(cur))
            for idx in order:
                if time.process_time() - t0 >= deadline:
                    break
                old = cur[idx]
                if old <= 1e-14:
                    continue
                bl, blc = old, curC
                for fac in (1.0 + step, 1.0 - step):
                    nv = old * fac
                    if nv < 0:
                        continue
