    nz = np.nonzero(h > 1e-12 * m)[0]
    if len(nz) == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _resample(h, N):
    if len(h) == N:
        return h.copy()
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    return np.maximum(np.interp(xnew, xold, h), 0)


def _conv_and_grad(h):
    """Return C, and gradient of C w.r.t. h using active set of near-max knots."""
    n = len(h)
    s = h.sum()
    conv = np.convolve(h, h)
    m = conv.max()
    coef = 2.0 * n
    C = coef * m / (s * s)
    # gradient through max: average over active knots
    ks = np.nonzero(conv >= m * (1 - 1e-9))[0]
    g = np.zeros(n)
    for k in ks:
        lo = max(0, k - n + 1)
        hi = min(n - 1, k)
        if hi >= lo:
            # j from lo..hi, partner = k - j
            js = np.arange(lo, hi + 1)
            g[js] += 2.0 * h[k - js]
    g /= len(ks)
    grad = coef * (g / (s * s) - 2.0 * m / (s * s * s))
    return C, grad, m, s


