def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.82

    def elapsed():
        return time.process_time() - t0

    rng = np.random.default_rng(1234567)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        m = h.max()
        if m > 0:
            h /= m
    else:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h = np.exp(-(x / 0.15) ** 2)

    h = _trim(h)
    best = h.copy()
    bestC = _C(best)
    bestN = len(best)

    # Cheap C using FFT for long arrays, direct for short
    def fast_C(cur):
        s = cur.sum()
        if s <= 0:
            return np.inf
        n = len(cur)
        if n * n <= 4_000_000:
            m = float(np.max(np.convolve(cur, cur)))
        else:
            L = 1
            while L < 2 * n:
                L <<= 1
            F = np.fft.rfft(cur, L)
            conv = np.fft.irfft(F * F, L)
            m = float(np.max(conv[:2 * n - 1]))
        return 2.0 * n * m / (s * s)

    def coord_descent(cur, curC, deadline, logstep0=0.03, min_step=1e-10):
        logstep = logstep0
        n = len(cur)
        while elapsed() < deadline:
            improved = False
            perm = rng.permutation(n)
            for idx in perm:
                if elapsed() >= deadline:
                    break
                old = cur[idx]
                if old <= 0:
                    continue
                bf, blc = 1.0, curC
                for fac in (np.exp(logstep), np.exp(-logstep)):
                    cur[idx] = old * fac
                    c = fast_C(cur)
                    if c < blc - 1e-17:
                        blc, bf = c, fac
                cur[idx] = old * bf
                if blc < curC - 1e-17:
                    curC = blc
                    improved = True
            if not improved:
                logstep *= 0.5
                if logstep < min_step:
                    break
        return cur, curC

    # Phase 1: polish start at its resolution
    cur, curC = best.copy(), bestC
    cur, curC = coord_descent(cur, curC, min(budget * 0.10, elapsed() + budget * 0.10), 0.04)
    if curC < bestC:
        bestC, best, bestN = curC, cur.copy(), len(cur)

    # Phase 2: ladder of resolutions. Interior sizes tend to win; test wide range.
    target = 30000
    ladder = []
    n = bestN
    while n < target:
        n = int(n * 1.12) + 1
        ladder.append(min(n, target))
