    for extra in (150, 250, 400, 600, 900, 1400, 2200, 3500, 5500, 8500):
        if extra <= target and extra not in ladder:
            ladder.append(extra)
    ladder = sorted(set(ladder))
    idxs = list(range(len(ladder)))
    mid = len(ladder) // 2
    idxs.sort(key=lambda i: abs(i - mid))
    order = [ladder[i] for i in idxs]

    tried_N = set([bestN])
