        cand = _resample(best, N1)
        candC = fast_C(cand)
        dl = min(phase2_deadline, elapsed() + budget * 0.035)
        cc, ccc = coord_descent(cand, candC, dl, 0.02)
        if ccc < bestC - 1e-14:
            bestC, best, bestN = ccc, cc.copy(), len(cc)

    # Phase 3: block perturbations at best resolution
    cur, curC = best.copy(), bestC
    block_steps = [(2, 0.03), (4, 0.02), (8, 0.012), (16, 0.008),
                   (4, 0.005), (8, 0.003), (2, 0.0015), (1, 0.0008)]
    bi = 0
    block_deadline = budget * 0.87
    while elapsed() < block_deadline:
        N = len(cur)
        bs, ls = block_steps[bi % len(block_steps)]
        bi += 1
        if N < bs:
            continue
        starts = rng.permutation(N - bs + 1)
        improved = False
        for s in starts:
            if elapsed() >= block_deadline:
                break
            sl = slice(s, s + bs)
            seg = cur[sl].copy()
            blc = curC
            bl = None
            for fac in (1 + ls, 1 - ls):
                cur[sl] = seg * fac
                c = fast_C(cur)
                if c < blc - 1e-17:
                    blc = c
                    bl = cur[sl].copy()
            if bl is not None:
                cur[sl] = bl
                curC = blc
                improved = True
            else:
