    cur, curC = best.copy(), bestC
    cur, curC = coord_descent(cur, curC, budget, 0.01, 1e-11)
    if curC < bestC:
        bestC, best = curC, cur.copy()

    best = _trim(best)
    if best.sum() <= 0:
        best = np.ones(50)
