    best = h.copy()
    bestC = _C(best)

    def fast_C(cur):
        s = cur.sum()
        if s <= 0:
            return np.inf
        n = len(cur)
        if n * n <= 2_000_000:
            m = float(np.max(np.convolve(cur, cur)))
        else:
            L = 1
            while L < 2 * n:
                L <<= 1
            F = np.fft.rfft(cur, L)
            conv = np.fft.irfft(F * F, L)
            m = float(np.max(conv[:2 * n - 1]))
        return 2.0 * n * m / (s * s)

