    # For C = 2N*M/S^2 with M = max(conv), consider scaling h[i] by factor t.
    # We approximate by treating the active-max constraint: pick the coordinate
    # and solve a local least-squares to reduce the peak while preserving sum.
    # Simpler effective version: multiplicative update using the gradient of the
    # peak location w.r.t. coordinate, plus sum-normalization, applied in blocks.

    def grad_step(cur, curC, deadline, lr0=0.05):
        """Peak-tracking gradient descent on C."""
        n = len(cur)
        lr = lr0
