            # gradient of conv[idx] w.r.t. h = 2*shift of h at idx
            # conv[idx] = sum_j h[j] h[idx-j]
            # d/dh[k] conv[idx] = h[idx-k] + h[idx-k] (symmetric) = 2 h[idx-k] (with dup)
            g = np.zeros(n)
            for k in range(n):
                a = idx - k
                if 0 <= a < n:
