def _convolve_full(h):
    n = len(h)
    L = 1
    while L < 2 * n:
        L <<= 1
    F = np.fft.rfft(h, L)
    conv = np.fft.irfft(F * F, L)
    return conv[:2 * n - 1]


def _fast_C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_convolve_full(h))) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.85

    def elapsed():
        return time.process_time() - t0

    rng = np.random.default_rng(1234567)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        m = h.max()
        if m > 0:
