    else:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h = np.exp(-(x / 0.15) ** 2)

    h = _trim(h)
    best = h.copy()
    bestC = _C(best)

    # Key insight: the true optimum is likely smooth and unimodal-ish.
    # We aggressively resample to high N early (fixed N=30000 typically helps)
    # and use a smooth parametric family (cosine bump) as alternative seed.

    def smooth_seed(N):
        x = np.linspace(-0.5, 0.5, N)
        # cosine bump on [-a, a]
        a = 0.35
        y = np.where(np.abs(x) < a, 0.5 * (1 + np.cos(np.pi * x / a)), 0.0)
        return np.maximum(y, 0)

    # Try smooth seeds at target resolutions to find better starting basin
    seeds = [best.copy()]
    for N in (100, 200, 500, 1000, 2000, 5000, 10000, 30000):
        s = smooth_seed(N)
        # also try scaled versions
        seeds.append(s)
        if len(best) != N:
            seeds.append(_resample(best, N))

    # Evaluate seeds quickly
    for s in seeds:
        if elapsed() > budget * 0.08:
            break
        c = _fast_C(s)
        if c < bestC:
            bestC, best = c, s.copy()

