    def C_and_grad(cur):
        n = len(cur)
        s = cur.sum()
        if s <= 0:
            return np.inf, None
        conv = _convolve_full(cur)
        M = float(np.max(conv))
        tol = 1e-13 * M
        idx = np.nonzero(conv >= M - tol)[0]
