        if elapsed() >= phase1_deadline:
            break
        cand = _resample(best, N)
        candC = _fast_C(cand)
        dl = min(phase1_deadline, elapsed() + (phase1_deadline - elapsed()) / 3)
        cc, ccc = gradient_descent(cand, candC, dl, 0.5, 300)
        if ccc < bestC - 1e-14:
            bestC, best = ccc, cc.copy()

    # Phase 2: more gradient descent at highest N
    cur, curC = _resample(best, 30000), 0.0
    curC = _fast_C(cur)
    if curC > bestC:
        cur = _resample(best, len(best))
        curC = bestC
    cur, curC = gradient_descent(cur, curC, budget * 0.75, 0.3, 400)
    if curC < bestC - 1e-15:
        bestC, best = curC, cur.copy()

    # Phase 3: coordinate descent for fine polish
    def coord_descent(cur, curC, deadline, logstep0=0.005, min_step=1e-12):
        logstep = logstep0
        n = len(cur)
        while elapsed() < deadline:
            improved = False
            perm = rng.permutation(n)
            for idx in perm:
                if elapsed() >= deadline:
                    break
                old = cur[idx]
                if old <= 0:
                    continue
                bf, blc = 1.0, curC
                for fac in (np.exp(logstep), np.exp(-logstep)):
                    cur[idx] = old * fac
                    c = _fast_C(cur)
                    if c < blc - 1e-18:
