        return Cval, dC

    def gradient_descent(cur, curC, deadline, lr0=0.5, max_iter=400):
        lr = lr0
        for _ in range(max_iter):
            if elapsed() >= deadline:
                break
            Cval, dC = C_and_grad(cur)
            if dC is None or not np.isfinite(Cval):
                break
            gnorm = np.linalg.norm(dC)
            if gnorm < 1e-18:
                break
            step = lr / (gnorm + 1e-30)
            new = cur - step * dC
            new = np.maximum(new, 0.0)
            sn = new.sum()
            if sn <= 0:
                break
            newC = fast_C(new)
            if newC < curC - 1e-16:
                cur = new
                curC = newC
                lr *= 1.3
            else:
                lr *= 0.5
                if lr < 1e-16:
                    break
        return cur, curC

    def coord_descent(cur, curC, deadline, logstep0=0.02, min_step=1e-12):
        logstep = logstep0
        n = len(cur)
        while elapsed() < deadline:
            improved = False
            perm = rng.permutation(n)
            for idx in perm:
                if elapsed() >= deadline:
                    break
                old = cur[idx]
                if old <= 0:
                    continue
                bf, blc = 1.0, curC
                for fac in (np.exp(logstep), np.exp(-logstep)):
                    cur[idx] = old * fac
                    c = fast_C(cur)
                    if c < blc - 1e-18:
                        blc, bf = c, fac
                cur[idx] = old * bf
                if blc < curC - 1e-18:
                    curC = blc
                    improved = True
            if not improved:
                logstep *= 0.5
                if logstep < min_step:
                    break
        return cur, curC

    # Try high resolution directly (the optimum seems to be smooth at N~100)
    # but also test larger N to exploit finer discretization.
    target = 30000
    grow_deadline = budget * 0.25
    candidates = []
    n = len(best)
    while n < target:
        n = int(n * 1.4) + 1
        n = min(n, target)
        candidates.append(n)
    for extra in (500, 1000, 2000, 4000, 8000, 16000, 30000):
        if extra <= target:
            candidates.append(extra)
    candidates = sorted(set([len(best)] + candidates))

    for N1 in candidates:
        if elapsed() >= grow_deadline:
            break
        cand = _resample(best, N1) if N1 != len(best) else best.copy()
        candC = fast_C(cand)
        dl = min(grow_deadline, elapsed() + budget * 0.02)
        cc, ccc = gradient_descent(cand, candC, dl, 0.3, 80)
        if ccc < bestC - 1e-14:
            bestC, best = ccc, cc.copy()

    # Phase 1: gradient descent at current best N
    cur, curC = best.copy(), bestC
    cur, curC = gradient_descent(cur, curC, budget * 0.5, 0.5, 600)
    if curC < bestC - 1e-15:
        bestC, best = curC, cur.copy()

    # Phase 2: coord descent
    cur, curC = best.copy(), bestC
    cur, curC = coord_descent(cur, curC, budget * 0.68, 0.006)
    if curC < bestC - 1e-15:
        bestC, best = curC, cur.copy()

    # Phase 3: block perturbations
    cur, curC = best.copy(), bestC
    block_steps = [(2, 0.008), (4, 0.006), (8, 0.004), (16, 0.003),
                   (4, 0.002), (2, 0.001), (1, 0.0006)]
    bi = 0
    block_deadline = budget * 0.88
    while elapsed() < block_deadline:
        N = len(cur)
        bs, ls = block_steps[bi % len(block_steps)]
        bi += 1
        if N < bs:
            continue
        starts = rng.permutation(N - bs + 1)
        improved = False
        for s in starts:
            if elapsed() >= block_deadline:
                break
            sl = slice(s, s + bs)
            seg = cur[sl].copy()
            blc = curC
            bl = None
            for fac in (1 + ls, 1 - ls):
                cur[sl] = seg * fac
                c = fast_C(cur)
                if c < blc - 1e-18:
                    blc = c
                    bl = cur[sl].copy()
            if bl is not None:
                cur[sl] = bl
                curC = blc
                improved = True
            else:
                cur[sl] = seg
        if curC < bestC - 1e-15:
            bestC, best = curC, cur.copy()
        if not improved and bi > 2 * len(block_steps):
            break

    # Phase 4: tight final polish
    cur, curC = best.copy(), bestC
    cur, curC = gradient_descent(cur, curC, budget * 0.95, 0.1, 150)
    if curC < bestC - 1e-15:
        bestC, best = curC, cur.copy()
    cur, curC = coord_descent(cur, curC, budget, 0.003, 1e-13)
    if curC < bestC:
        bestC, best = curC, cur.copy()

    best = _trim(best)
    if best.sum() <= 0:
        best = np.ones(50)
    if len(best) > 30000:
        best = _resample(best, 30000)
    return best

