import time


def _convolve_full(h):
    n = len(h)
    L = 1
    while L < 2 * n:
        L <<= 1
    F = np.fft.rfft(h, L)
    return np.fft.irfft(F * F, L)[:2 * n - 1]


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_convolve_full(h))) / (s * s)


def _trim(h):
    m = h.max()
    if m <= 0:
        return h
    nz = np.nonzero(h > 1e-10 * m)[0]
    if len(nz) == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _resample(h, N):
    if len(h) == N:
        return h.copy()
    xo = np.linspace(0, 1, len(h))
    xn = np.linspace(0, 1, N)
    return np.maximum(np.interp(xn, xo, h), 0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.85

    def el():
        return time.process_time() - t0

    rng = np.random.default_rng(20240607)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        m = h.max()
        if m > 0:
            h /= m
    else:
        x = np.linspace(-0.5, 0.5, 200)
        h = np.exp(-(x / 0.25) ** 2)

    h = _trim(h)
    best = h.copy()
    bestC = _C(best)

    def C_and_grad(cur):
        n = len(cur)
        s = cur.sum()
        if s <= 0:
            return np.inf, None
        conv = _convolve_full(cur)
        M = float(np.max(conv))
        tol = 1e-12 * M
        idx = np.nonzero(conv >= M - tol)[0]
        Cval = 2.0 * n * M / (s * s)
        grad = np.zeros(n)
        for k in idx:
            lo = max(0, k - (n - 1))
            hi = min(n - 1, k)
            ii = np.arange(lo, hi + 1)
            grad[ii] += 2.0 * cur[k - ii]
        grad /= len(idx)
        dC = (2.0 * n / (s * s)) * grad - (4.0 * n * M / (s ** 3))
        return Cval, dC

