    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _convolve_full(h):
    n = len(h)
    L = 1
    while L < 2 * n:
        L <<= 1
    F = np.fft.rfft(h, L)
    return np.fft.irfft(F * F, L)[:2 * n - 1]


def _fast_C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_convolve_full(h))) / (s * s)


def _trim(h):
    m = h.max()
    if m <= 0:
        return h
    nz = np.nonzero(h > 1e-12 * m)[0]
    if len(nz) == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _resample(h, N):
    if len(h) == N:
        return h.copy()
    xold = np.linspace(0, 1, len(h))
    xnew = np.linspace(0, 1, N)
    return np.maximum(np.interp(xnew, xold, h), 0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.85

    def elapsed():
        return time.process_time() - t0

    rng = np.random.default_rng(987654321)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        m = h.max()
        if m > 0:
            h /= m
        h = _trim(h)
    else:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h = np.exp(-(x / 0.15) ** 2)

    best = h.copy()
    bestC = _fast_C(best)

    # --- SMOOTH PARAMETRIC SEED: the true optimum resembles a rounded
    # trapezoid / smooth bump. Use a family and pick the best. ---
    def bump(N, p):
        # p in [0,1]: blend between cosine and gaussian-ish bump
        x = np.linspace(-0.5, 0.5, N)
        a = 0.35
        cos = np.where(np.abs(x) < a, 0.5 * (1 + np.cos(np.pi * x / a)), 0.0)
        g = np.exp(-(x / 0.18) ** 2)
        return np.maximum((1 - p) * cos + p * g, 0)

    for N in (100, 200, 500, 1000, 2000):
        for p in (0.0, 0.25, 0.5, 0.75, 1.0):
            s = bump(N, p)
            c = _fast_C(s)
            if c < bestC:
