        M = float(np.max(conv))
        tol = 1e-12 * M
        idx = np.nonzero(conv >= M - tol)[0]
        Cval = 2.0 * n * M / (s * s)
        grad = np.zeros(n)
        for k in idx:
            i_lo = max(0, k - (n - 1))
            i_hi = min(n - 1, k)
            ii = np.arange(i_lo, i_hi + 1)
            grad[ii] += 2.0 * cur[k - ii]
        grad /= len(idx)
        dC = (2.0 * n / (s * s)) * grad - (4.0 * n * M / (s * s * s))
        return Cval, dC

