    cur = _resample(best, 30000)
    curC = _fast_C(cur)
    cur, curC = gradient_descent(cur, curC, budget * 0.80, 0.3, 300)
    if curC < bestC - 1e-15:
        bestC, best = curC, cur.copy()

    # Phase 3: coordinate descent for fine polish at high N
    def coord_descent(cur, curC, deadline, logstep0=0.004, min_step=1e-11):
        logstep = logstep0
        n = len(cur)
        while elapsed() < deadline:
            improved = False
            perm = rng.permutation(n)
            for idx in perm:
                if elapsed() >= deadline:
                    break
                old = cur[idx]
                if old <= 0:
                    continue
                bf, blc = 1.0, curC
                for fac in (np.exp(logstep), np.exp(-logstep)):
                    cur[idx] = old * fac
                    c = _fast_C(cur)
                    if c < blc - 1e-18:
                        blc, bf = c, fac
                cur[idx] = old * bf
                if blc < curC - 1e-18:
                    curC = blc
                    improved = True
            if not improved:
                logstep *= 0.5
                if logstep < min_step:
                    break
        return cur, curC

    cur, curC = best.copy(), bestC
    # Polish at moderate N then resample back (coordinate descent is O(N) per step)
    if len(cur) > 8000:
        Nmid = 6000
        mid = _resample(cur, Nmid)
        midC = _fast_C(mid)
        mid, midC = coord_descent(mid, midC, budget * 0.88, 0.004)
        cand = _resample(mid, len(best))
        candC = _fast_C(cand)
        if candC < bestC:
