import time


def _conv(h):
    n = len(h)
    L = 1
    while L < 2 * n:
        L <<= 1
    F = np.fft.rfft(h, L)
    return np.fft.irfft(F * F, L)[:2 * n - 1]


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(_conv(h))) / (s * s)


def _trim(h):
    m = h.max()
    if m <= 0:
        return h
    nz = np.nonzero(h > 1e-10 * m)[0]
    if len(nz) == 0:
        return h
    return h[nz[0]:nz[-1] + 1]


def _resample(h, N):
    if len(h) == N:
        return h.copy()
    xo = np.linspace(0, 1, len(h))
    xn = np.linspace(0, 1, N)
    return np.maximum(np.interp(xn, xo, h), 0)


def _grad(h):
    """Gradient of C w.r.t. h at current h (only max knot contributes)."""
    n = len(h)
    s = h.sum()
    if s <= 0:
        return np.zeros(n), np.inf
    conv = _conv(h)
    k = int(np.argmax(conv))
    M = conv[k]
    Cval = 2.0 * n * M / (s * s)
    # d/dh_i of conv[k] = 2 * h[k-i] (if in range), with h[-1] convention
    dM = np.zeros(n)
    # conv[k] = sum_j h[j] h[k-j], j in [0,n-1], k-j in [0,n-1]
    jlo = max(0, k - (n - 1))
    jhi = min(n - 1, k)
    # dM[j] += 2*h[k-j]
    for j in range(jlo, jhi + 1):
        dM[j] += 2.0 * h[k - j]
    g = 2.0 * n * dM / (s * s) - 4.0 * n * M / (s * s * s)
    return g, Cval


def _refine_max(h, budget, elapsed, iters=400):
    """Coordinate-ascent style: focus on the max knot, do projected gradient."""
    n = len(h)
    h = h.copy()
    c = _C(h)
    lr = 0.5 / max(c, 1e-9)
    for it in range(iters):
        if elapsed() >= budget:
            break
        g, _ = _grad(h)
        # normalize step size by gradient magnitude
        gn = np.linalg.norm(g)
        if gn < 1e-15:
            break
        step = lr * gn
        trial = np.maximum(h - step * g / gn, 0.0)
        ct = _C(trial)
        if ct < c:
            h, c = trial, ct
            lr *= 1.2
        else:
            lr *= 0.5
            if lr < 1e-12:
                break
    return h, c


def _pairwise_solve(h, budget, elapsed, sweeps=30):
    """For each pair (i,j) with small support, solve 2-var locally by scanning."""
    n = len(h)
    h = h.copy()
    c = _C(h)
    rng = np.random.default_rng(7)
    for sw in range(sweeps):
        if elapsed() >= budget:
            break
        improved = False
        order = rng.permutation(n)
        i = 0
        while i < len(order) - 1:
            if elapsed() >= budget:
                break
            a, b = order[i], order[i + 1]
            oa, ob = h[a], h[b]
            best_local = (c, oa, ob)
            # try a small grid of perturbations
            for da in (0.0, 0.01, -0.01, 0.05, -0.05):
                for db in (0.0, 0.01, -0.01, 0.05, -0.05):
                    if da == 0.0 and db == 0.0:
                        continue
                    h[a] = max(oa + da * oa, 0.0)
                    h[b] = max(ob + db * ob, 0.0)
                    cn = _C(h)
                    if cn < best_local[0]:
                        best_local = (cn, h[a], h[b])
            h[a], h[b] = best_local[1], best_local[2]
            if best_local[0] < c - 1e-15:
                c = best_local[0]
                improved = True
            else:
                h[a], h[b] = oa, ob
            i += 2
        if not improved:
            break
    return h, c


