def _smooth_max_obj(n, beta):
    def f(v):
        h = np.maximum(v, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e10, np.zeros(n)
        conv = _conv(h)
        M = conv.max()
        e = np.exp(beta * (conv - M))
        Z = e.sum()
        sm = (e @ conv) / Z
        Cval = 2.0 * n * sm / (s * s)
        es = e / Z
        dsm = es * (1.0 + beta * (conv - sm))
        gs = 2.0 * np.convolve(dsm, h[::-1])[n - 1:n - 1 + n]
        dC = 2.0 * n / (s * s) * gs - 4.0 * n * sm / (s * s * s)
        return Cval, dC
    return f


def _max_obj(n):
    # Hard-max objective with subgradient (spreads ties).
    def f(v):
        h = np.maximum(v, 0.0)
        s = h.sum()
        if s <= 0:
            return 1e10, np.zeros(n)
        conv = _conv(h)
        M = conv.max()
        Cval = 2.0 * n * M / (s * s)
        mask = conv >= M - 1e-12 * max(1.0, abs(M))
        w = mask.astype(float)
        w /= w.sum()
        gs = 2.0 * np.convolve(w, h[::-1])[n - 1:n - 1 + n]
        dC = 2.0 * n / (s * s) * gs - 4.0 * n * M / (s * s * s)
