def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds * 0.88

    def elapsed():
        return time.process_time() - t0

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        m = h0.max()
        if m > 0:
            h0 /= m
        h0 = _trim(h0)
    else:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h0 = np.exp(-(x / 0.15) ** 2)

    best = h0.copy()
    bestC = _C(best)

    def make_soft(n, beta):
        def f(v):
            h = np.maximum(v, 0.0)
            s = h.sum()
            if s <= 0:
                return 1e10, np.zeros(n)
            conv = _conv(h)
            M = conv.max()
            e = np.exp(beta * (conv - M))
            Z = e.sum()
            sm = (e @ conv) / Z
            Cval = 2.0 * n * sm / (s * s)
            es = e / Z
            dsm = es * (1.0 + beta * (conv - sm))
            gs = 2.0 * np.convolve(dsm, h[::-1])[n - 1:n - 1 + n]
            dC = 2.0 * n / (s * s) * gs - 4.0 * n * sm / (s * s * s)
            return Cval, dC
        return f

    def make_hard(n):
        # exact max with subgradient over argmax set
        def f(v):
            h = np.maximum(v, 0.0)
            s = h.sum()
            if s <= 0:
                return 1e10, np.zeros(n)
            conv = _conv(h)
            M = conv.max()
            tol = 1e-12 * max(1.0, abs(M))
            mask = (conv >= M - tol)
            w = mask.astype(float)
            w /= w.sum()
            Cval = 2.0 * n * M / (s * s)
            gs = 2.0 * np.convolve(w, h[::-1])[n - 1:n - 1 + n]
            dC = 2.0 * n / (s * s) * gs - 4.0 * n * M / (s * s * s)
