        h0 = _trim(h0)
    else:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h0 = np.exp(-(x / 0.15) ** 2)

    best = h0.copy()
    bestC = _C(best)

    def make_obj(n, beta):
        def f(v):
            h = np.maximum(v, 0.0)
            s = h.sum()
            if s <= 0:
                return 1e10, np.zeros(n)
